import mq3.client.ui_signup as s
import mq3.client.ui_rankings as r
import mq3.client.ui_qmenu as q
function req(ok,label) if not ok then return error(7994,"signup: "+label) end if;return 1 end function
function main(args) count=0;v=s.create(false);s.Signup_MenuInit(v,r.QGR_STATUS_NEW);count=count+req(len(v.menu.items)==11 and v.frame.name==s.SIGNUP_FRAME,"menu and frame");count=count+req(v.name.string=="NAME" and v.again.string=="(AGAIN)" and v.email.string=="EMAIL" and v.signup.string=="SIGN UP","labels");count=count+req(v.emailBox.maxchars==255 and v.nameBox.maxchars==16,"field bounds");v.nameBox.buffer="Hero";v.passwordBox.buffer="one";v.againBox.buffer="two";v.emailBox.buffer="h@example.org";count=count+req(not s.Signup_MenuEvent(v,s.ID_SIGNUP,q.QM_ACTIVATED) and not v.forcedOff,"password mismatch");v.againBox.buffer="one";count=count+req(s.Signup_MenuEvent(v,s.ID_SIGNUP,q.QM_ACTIVATED) and v.forcedOff,"create account");a=v.actions[len(v.actions)-2];count=count+req(a.kind=="create-user" and a.text=="Hero" and a.text2=="one" and a.text3=="h@example.org","typed create fields");locked=s.create(false);s.Signup_MenuInit(locked,r.QGR_STATUS_ACTIVE);count=count+req((locked.nameBox.flags&q.QMF_INACTIVE)!=0 and (locked.signup.flags&q.QMF_INACTIVE)!=0,"active status lock");cancel=s.create(false);s.Signup_MenuInit(cancel,r.QGR_STATUS_NEW);count=count+req(s.Signup_MenuEvent(cancel,s.ID_CANCEL,q.QM_ACTIVATED) and cancel.popped,"cancel");open=s.create(true);s.UI_SignupMenu(open,r.QGR_STATUS_NEW);ok=true;for each x in open.actions if x.dispatched then ok=false end if end for;count=count+req(open.pushed and ok,"push and suppression");print("PASS: "+str(count)+" UI signup contracts");return 0 end function
